"""
recipes.py - Recipe scaler and shopping list generator.

Features:
- Unit conversion between supported units of volume, weight, and count
- Ingredient merging (sum quantities of the same ingredient)
- Scaling ingredient quantities by serving count
- Pantry subtraction step to remove ingredients already present

Configuration loaded from config.json for units, aisles, and pantry state.
"""

import json
from collections import defaultdict
from typing import Dict, List, Tuple, Optional

CONFIG_PATH = "config.json"


def load_config(path: str = CONFIG_PATH) -> Dict:
    """Load configuration from JSON file."""
    with open(path, "r") as f:
        return json.load(f)


class UnitConverter:
    def __init__(self, units_config: Dict[str, Dict[str, float]]):
        self.units_config = units_config
        self.unit_type_map = {}
        for t, units in units_config.items():
            for unit in units:
                self.unit_type_map[unit] = t

    def convert(self, qty: float, from_unit: str, to_unit: str) -> Optional[float]:
        """Convert qty from from_unit to to_unit, or None if incompatible."""
        if from_unit == to_unit:
            return qty
        from_type = self.unit_type_map.get(from_unit)
        to_type = self.unit_type_map.get(to_unit)
        if not from_type or not to_type or from_type != to_type:
            return None
        base_qty = qty * self.units_config[from_type][from_unit]
        to_qty = base_qty / self.units_config[to_type][to_unit]
        return to_qty


class RecipeScaler:
    def __init__(self, config: Dict):
        self.config = config
        self.converter = UnitConverter(config["units"])

    def scale_ingredients(self, ingredients: List[Tuple[str, float, str]], base_servings: int, new_servings: int) -> List[Tuple[str, float, str]]:
        """Scale ingredient quantities according to new_servings ratio."""
        scale_factor = new_servings / base_servings
        scaled = [(name, qty * scale_factor, unit) for (name, qty, unit) in ingredients]
        return scaled

    def merge_ingredients(self, ingredients: List[Tuple[str, float, str]]) -> List[Tuple[str, float, str]]:
        """Merge quantities of the same ingredient."""
        merged = {}
        for name, qty, unit in ingredients:
            if name in merged:
                # Convert existing quantity to current unit if possible
                prev_qty, prev_unit = merged[name]
                conv_qty = self.converter.convert(prev_qty, prev_unit, unit)
                if conv_qty is not None:
                    merged[name] = (conv_qty + qty, unit)
                else:
                    # Not convertible, store separately as a fallback (could be extended)
                    # For now, override with a tuple and track units
                    if isinstance(merged[name], list):
                        merged[name].append((qty, unit))
                    else:
                        merged[name] = [merged[name], (qty, unit)]
            else:
                merged[name] = (qty, unit)

        # Flatten merged again for output, if multiples are stored
        result = []
        for name, val in merged.items():
            if isinstance(val, list):
                # produce separate entries
                for qty, unit in val:
                    result.append((name, qty, unit))
            else:
                result.append((name, val[0], val[1]))
        return result

    def subtract_pantry(self, ingredients: List[Tuple[str, float, str]], pantry: Dict[str, float]) -> List[Tuple[str, float, str]]:
        """Subtract pantry quantities from ingredients."""
        result = []
        for name, qty, unit in ingredients:
            pantry_qty = pantry.get(name, 0)
            pantry_unit = self.config["pantry_units"].get(name)
            if pantry_qty > 0 and pantry_unit:
                conv_pantry_qty = self.converter.convert(pantry_qty, pantry_unit, unit)
                if conv_pantry_qty is not None:
                    new_qty = qty - conv_pantry_qty
                    if new_qty > 0:
                        result.append((name, new_qty, unit))
                    # else fully accounted for
                else:
                    # Can't convert pantry quantity, just keep all
                    result.append((name, qty, unit))
            else:
                # Ingredient not in pantry
                result.append((name, qty, unit))
        return result


def generate_shopping_list(scaled_ingredients: List[Tuple[str, float, str]], 
                           config: Dict, 
                           pantry: Optional[Dict[str, float]] = None) -> List[Tuple[str, float, str]]:
    """Generate merged, pantry-subtracted shopping list."""
    scaler = RecipeScaler(config)
    merged = scaler.merge_ingredients(scaled_ingredients)

    if pantry is None:
        pantry = {}

    shopping = scaler.subtract_pantry(merged, pantry)
    return shopping


def example_demo():
    """Run an example demo printing scaled recipe and shopping list."""
    config = load_config()

    # Derive pantry units mapping
    config["pantry_units"] = config["pantry"]

    # Example recipe (serves 4)
    ingredients = [
        ("flour", 2, "cup"),
        ("sugar", 1.5, "cup"),
        ("butter", 4, "tbsp"),
        ("eggs", 2, "each"),
        ("milk", 1, "cup"),
        ("vanilla extract", 2, "tsp")
    ]

    base_servings = 4
    new_servings = 6

    scaler = RecipeScaler(config)
    scaled = scaler.scale_ingredients(ingredients, base_servings, new_servings)

    print("Scaled Ingredients for", new_servings, "servings:")
    for name, qty, unit in scaled:
        print(f"- {name}: {qty:.2f} {unit}")

    # Example pantry quantities
    pantry = {
        "flour": 1.0,  # cups
        "sugar": 0.5,  # cups
        "butter": 2,   # tbsp
        "eggs": 1      # each
    }

    shopping_list = generate_shopping_list(scaled, config, pantry)

    print("\nShopping List (after pantry subtraction):")
    for name, qty, unit in shopping_list:
        print(f"- {name}: {qty:.2f} {unit}")


if __name__ == "__main__":
    example_demo()
